48			tok = strim(tok);
49	
50			if (first) {
51				first = false;
52	
53				if (!strcmp(tok, "auto"))
54					continue;
55	
56				new = 0;
57				if (!strcmp(tok, "off"))
58					continue;
59			}
60	
61			if (*tok == '!') {
62				enable = !enable;
63				tok++;
64			}
65	
66			if (!strncmp(tok, "no", 2)) {
