74			for (i = 0; i < ARRAY_SIZE(names); i++) {
75				if (!strcmp(tok, names[i])) {
76					if (enable)
77						new |= BIT(i);
78					else
79						new &= ~BIT(i);
80					break;
81				}
82			}
83			if (i == ARRAY_SIZE(names)) {
